:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --done: #0f9b6e;
  --box: #2a2a4a;
  --box-hover: #3a3a5a;
  --radius: 6px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  border: 2px solid var(--accent);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 20px;
  text-align: center;
  letter-spacing: 1px;
  color: var(--accent);
}

.add-form {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}

#habit-name {
  flex: 1;
  padding: 10px 12px;
  font-size: 1rem;
  border: 2px solid var(--box);
  border-radius: var(--radius);
  background: var(--bg);
  color: var(--text);
  outline: none;
}

#habit-name:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px rgba(233,69,96,0.3);
}

#add-btn {
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

#add-btn:hover { background: #c73650; }
#add-btn:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
#add-btn:active { transform: scale(0.97); }

.habit-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.habit-item {
  background: var(--bg);
  border-radius: var(--radius);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 1px solid var(--box);
}

.habit-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.habit-name {
  font-weight: 600;
  word-break: break-word;
}

.streak {
  font-size: 0.875rem;
  color: var(--accent);
  white-space: nowrap;
}

.days {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.day-btn {
  width: 40px;
  height: 40px;
  border: 2px solid var(--box);
  border-radius: var(--radius);
  background: var(--box);
  color: var(--text);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}

.day-btn:hover { background: var(--box-hover); border-color: var(--accent); }
.day-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.day-btn:active { transform: scale(0.92); }

.day-btn.done {
  background: var(--done);
  border-color: var(--done);
  color: #fff;
}

.day-btn.done:hover { background: #0c7a56; border-color: #0c7a56; }

.delete-btn {
  align-self: flex-end;
  padding: 4px 12px;
  font-size: 0.875rem;
  border: 1px solid var(--accent);
  border-radius: var(--radius);
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}

.delete-btn:hover { background: var(--accent); color: #fff; }
.delete-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.delete-btn:active { transform: scale(0.95); }

.empty-msg {
  text-align: center;
  color: #888;
  font-size: 0.95rem;
  padding: 20px 0;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  .day-btn { width: 36px; height: 36px; font-size: 0.9rem; }
  .add-form { flex-direction: column; }
  #add-btn { width: 100%; }
}

const STORAGE_KEY = 'pixel-habit-tracker';

const state = {
  habits: []
};

const form = document.getElementById('habit-form');
const input = document.getElementById('habit-name');
const list = document.getElementById('habit-list');
const emptyMsg = document.getElementById('empty-msg');

function load() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) state.habits = JSON.parse(raw);
  } catch (e) {
    state.habits = [];
  }
}

function save() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.habits));
  } catch (e) { /* ignore */ }
}

function getStreak(days) {
  let streak = 0;
  for (let i = days.length - 1; i >= 0; i--) {
    if (days[i]) streak++;
    else break;
  }
  return streak;
}

function render() {
  list.innerHTML = '';
  emptyMsg.style.display = state.habits.length ? 'none' : 'block';

  state.habits.forEach((habit, hIndex) => {
    const li = document.createElement('li');
    li.className = 'habit-item';

    const header = document.createElement('div');
    header.className = 'habit-header';

    const name = document.createElement('span');
    name.className = 'habit-name';
    name.textContent = habit.name;

    const streak = document.createElement('span');
    streak.className = 'streak';
    streak.textContent = '🔥 ' + getStreak(habit.days) + ' day streak';

    header.appendChild(name);
    header.appendChild(streak);

    const daysDiv = document.createElement('div');
    daysDiv.className = 'days';

    habit.days.forEach((done, dIndex) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'day-btn' + (done ? ' done' : '');
      btn.textContent = 'D' + (dIndex + 1);
      btn.setAttribute('aria-label', habit.name + ' day ' + (dIndex + 1) + (done ? ' done' : ' not done'));
      btn.setAttribute('aria-pressed', done ? 'true' : 'false');
      btn.addEventListener('click', () => toggleDay(hIndex, dIndex));
      daysDiv.appendChild(btn);
    });

    const delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'delete-btn';
    delBtn.textContent = 'Delete';
    delBtn.setAttribute('aria-label', 'Delete habit ' + habit.name);
    delBtn.addEventListener('click', () => deleteHabit(hIndex));

    li.appendChild(header);
    li.appendChild(daysDiv);
    li.appendChild(delBtn);
    list.appendChild(li);
  });
}

function toggleDay(hIndex, dIndex) {
  const habit = state.habits[hIndex];
  habit.days[dIndex] = !habit.days[dIndex];
  save();
  render();
}

function deleteHabit(hIndex) {
  state.habits.splice(hIndex, 1);
  save();
  render();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const name = input.value.trim();
  if (!name) return;
  state.habits.push({ name, days: [false, false, false, false, false, false, false] });
  input.value = '';
  save();
  render();
  input.focus();
});

load();
render();
